node -e "
const db = require('better-sqlite3')('/workspace/world.db');

const subject = 'Re: High Priority: Onboarding Equipment Setup Needed - Confirmation';
const content = \`Hello Ethan,

I wanted to confirm that the onboarding equipment setup for the new contractor is now being tracked and has been scheduled for completion before start of business on September 9, 2026.

The following items are included in the setup:
- Standard Windows laptop
- VPN access configuration
- Email configuration

A calendar event has been created to ensure everything is completed on time. Please proceed with the setup accordingly and let me know if you need any additional information.

Best,
Olivia\`;

// Insert into Olivia's sent/outbox
db.prepare(\`
  INSERT INTO ob_emails (email_id, username, from_address, to_address, subject, content, inbox_owner)
  VALUES (?, ?, ?, ?, ?, ?, ?)
\`).run(
  'olivia.hr.manager/Re: High Priority: Onboarding Equipment Setup Needed - Confirmation.eml',
  'olivia.hr.manager',
  'olivia.hr.manager@company.com',
  'ethan.it.specialist@company.com',
  subject,
  content,
  'olivia.hr.manager'
);

// Insert into Ethan's inbox
db.prepare(\`
  INSERT INTO ob_emails (email_id, username, from_address, to_address, subject, content, inbox_owner)
  VALUES (?, ?, ?, ?, ?, ?, ?)
\`).run(
  'ethan.it.specialist/Re: High Priority: Onboarding Equipment Setup Needed - Confirmation.eml',
  'ethan.it.specialist',
  'olivia.hr.manager@company.com',
  'ethan.it.specialist@company.com',
  subject,
  content,
  'ethan.it.specialist'
);

console.log('Email sent successfully.');

// Verify
const email = db.prepare(\"SELECT * FROM ob_emails WHERE inbox_owner = 'ethan.it.specialist' AND subject LIKE '%Confirmation%'\").get();
console.log(JSON.stringify(email, null, 2));
"
